/**
 * Internal-only idempotency key for one logical outbound call request.
 * The key is generated by the server from the current agent run; callers
 * never supply it as a model-visible tool argument.
 */
export function normalizePhoneCallRequestKey(value: unknown): string | undefined {
  if (value === undefined || value === null || value === "") return undefined;
  const key = String(value).trim();
  if (!/^pc_[a-f0-9]{64}$/.test(key)) throw new Error("Invalid phone call request key");
  return key;
}
